// Everything comes from the Kook settings node of whichever workflow called this one.
const i = $input.first().json;
const provider = String(i.VOICE_PROVIDER || 'bland').toLowerCase();
return [{ json: {
  provider,
  to_number: i.TEST_MODE ? i.MY_PHONE : i.BAKERY_PHONE,   // TEST_MODE rings your own phone
  bakery_name: i.BAKERY_NAME || 'the bakery',
  order: i.ORDER || 'a pie and a custard tart',
  pickup_minutes: String(i.PICKUP_IN_MIN || 15),
  customer_name: i.CUSTOMER_NAME || 'YOUR_NAME',
  elevenlabs_agent_id: i.ELEVENLABS_AGENT_ID || '',
  elevenlabs_phone_number_id: i.ELEVENLABS_PHONE_NUMBER_ID || '',
  bland_voice: i.BLAND_VOICE || 'mason',
  telegram_chat_id: i.TELEGRAM_CHAT_ID,
} }];
